import Link from "next/link"; import { Definition, Section } from "@/components/ui"; import { JsonLd,breadcrumb } from "@/lib/schema"; import { site } from "@/lib/site";
export function ArticlePage({title,description,children,path}:{title:string;description:string;children:React.ReactNode;path:string}){return <><JsonLd data={[breadcrumb([{name:"Home",path:"/"},{name:title,path}]),{"@context":"https://schema.org","@type":"Article",headline:title,description,author:{"@type":"Person",name:site.author},reviewedBy:{"@type":"Person",name:site.reviewer},publisher:{"@type":"Organization",name:site.name},dateModified:"2026-07-24"}]}/><section className="bg-mint py-16 dark:bg-teal-950"><div className="container max-w-4xl"><p className="text-sm font-bold uppercase tracking-widest text-teal-700">BMI Index Calculator · Health guide</p><h1 className="mt-4 text-4xl font-extrabold tracking-tight md:text-5xl">{title}</h1><p className="mt-5 max-w-2xl text-lg leading-8 text-slate-600 dark:text-slate-300">{description}</p><p className="mt-5 text-sm text-slate-500">Written by {site.author} · Medically reviewed by {site.reviewer} · Updated July 24, 2026</p></div></section><Section title=""><article className="prose-health max-w-4xl">{children}<p className="mt-10 rounded-xl bg-slate-100 p-4 text-sm dark:bg-slate-800">This material is for education and does not replace personal medical advice. <Link href="/disclaimer" className="text-teal-700 underline">Read the medical disclaimer.</Link></p></article></Section></>}
export function BasicLegal({title,children}:{title:string;children:React.ReactNode}){return <section className="container max-w-3xl py-16"><h1 className="text-4xl font-extrabold">{title}</h1><article className="prose-health mt-8">{children}</article></section>}
